-- ===============================================================
-- universe67: 📖 메뉴 '자세히 보기' — 홈페이지가 있는 업체 4곳 (응오 · 스완 · 골든 로터스 · 라벨비)
--  가게 홈페이지 · 메뉴판의 사실만 뽑아 엉클데이 말투로 새로 썼어요 (원문 문장을 옮기지 않았어요)
--  휴대폰에서 읽기 쉽게 한 문장씩 줄을 바꿨어요 · 한국어 · 영어 · 베트남어
--  닥터 하버드(성형 · 시술)는 의료 정보라 넣지 않았어요
--  메뉴 영어 이름(name.en)이 같은 줄에만 붙여요 · 이름 · 시간 · 가격은 안 바꿔요 · 여러 번 실행해도 같아요
--  ⚠️ 실행 뒤 열어 둔 관리자 화면은 새로고침(F5) 해 주세요
-- ===============================================================

-- ngo-massage-spa · 22종
with t as (select $j${"Aroma Massage": {"ko": "천연 에센셜 오일로 하는 전신 마사지예요.\n은은한 향과 함께 천천히 풀어 줘서 푹 쉬고 싶을 때 좋아요.", "en": "Full-body massage with natural essential oils.\nGentle scent and a slow rhythm — good when you just want to rest.", "vi": "Massage toàn thân với tinh dầu thiên nhiên.\nHương thơm dịu nhẹ, nhịp chậm — hợp khi muốn nghỉ ngơi thật sự."}, "Meridian Unblocking Therapy": {"ko": "혈자리를 눌러 주고 근육을 늘려 주는 마사지예요.\n막히고 뭉친 곳을 풀어 주는 쪽이라 세게 받고 싶은 분께 맞아요.", "en": "Acupressure combined with muscle stretching.\nIt works on blocked, knotted spots — good if you like firm pressure.", "vi": "Day ấn huyệt kết hợp kéo căng cơ.\nGiải tỏa các điểm tắc nghẽn — hợp với người thích lực mạnh."}, "Basalt Hot Stone Therapy": {"ko": "데운 현무암 돌과 천연 오일로 전신을 풀어 주는 마사지예요.\n돌의 열이 깊이 전해져 몸이 금방 따뜻해져요.", "en": "Heated basalt stones with natural oil, all over the body.\nThe warmth goes deep and warms you up quickly.", "vi": "Đá Bazan làm nóng kết hợp tinh dầu thiên nhiên, massage toàn thân.\nHơi ấm thấm sâu, làm ấm cơ thể nhanh."}, "Candle Massage": {"ko": "캔들을 녹인 따뜻한 오일로 하는 마사지예요.\n오일이 따뜻해서 피부가 촉촉해지고 몸이 부드럽게 풀려요.", "en": "Massage with warm oil from a melted candle.\nThe warm oil leaves skin soft and helps you unwind.", "vi": "Massage bằng dầu ấm từ nến tan chảy.\nDầu ấm giúp da mềm mại và cơ thể thư giãn."}, "Himalayan Salt Stone Massage": {"ko": "따뜻하게 데운 히말라야 소금돌로 문질러 주는 마사지예요.\n핫스톤과 비슷하지만 소금돌만의 매끈한 느낌이 있어요.", "en": "Massage with warmed Himalayan salt stones.\nSimilar to hot stones, with the smooth feel of salt stone.", "vi": "Massage bằng đá muối Himalaya được làm ấm.\nGiống đá nóng nhưng có cảm giác mịn của đá muối."}, "Herbal Ball Therapy": {"ko": "따뜻한 허브볼로 찜질하면서 지압과 스트레칭을 함께 해요.\n몸이 무겁고 피곤할 때 좋아요.", "en": "Warm herbal balls combined with acupressure and stretching.\nGood when your body feels heavy and tired.", "vi": "Bóng thảo dược ấm kết hợp ấn huyệt và kéo giãn.\nHợp khi cơ thể nặng nề, mệt mỏi."}, "Ngõ's Signature": {"ko": "응오에서만 받을 수 있는 대표 마사지예요.\n경락 마사지에 타이식 스트레칭을 섞어서 시원하게 풀어 줘요.", "en": "Ngõ's own signature treatment.\nMeridian massage blended with traditional Thai stretching.", "vi": "Liệu pháp độc quyền của Ngõ.\nKết hợp đả thông kinh lạc và kéo căng cơ kiểu Thái."}, "Relaxing Foot Therapy": {"ko": "가볍게 받는 발 마사지예요.\n하루 종일 걸어 다닌 날 짧게 쉬어 가기 좋아요.", "en": "A light foot massage.\nA quick break after a long day on your feet.", "vi": "Massage chân nhẹ nhàng.\nNghỉ ngơi nhanh sau một ngày đi nhiều."}, "Hot Stone Foot Therapy": {"ko": "데운 현무암 돌과 따뜻한 오일로 발을 풀고, 발 혈자리를 눌러 줘요.\n붓고 무거운 다리에 좋아요.", "en": "Heated basalt stones and warm oil on the feet, plus foot acupressure.\nGreat for swollen, heavy legs.", "vi": "Đá Bazan nóng và dầu ấm cho bàn chân, kèm bấm huyệt.\nHợp với chân sưng, nặng."}, "Head, Shoulder & Neck Therapy": {"ko": "머리 · 어깨 · 목만 집중해서 풀어 줘요.\n비행기 · 버스로 오래 앉아 있어 목이 뻐근할 때 좋아요.", "en": "Focused work on the head, shoulders and neck.\nGood after long flights or bus rides.", "vi": "Tập trung vào đầu, vai, cổ.\nHợp sau những chuyến bay, xe dài."}, "Head, Shoulder & Back Therapy": {"ko": "머리 · 어깨 · 등을 집중해서 풀어 줘요.\n전신은 부담스럽고 상체만 시원하게 받고 싶을 때 좋아요.", "en": "Focused work on the head, shoulders and back.\nWhen you want just the upper body done.", "vi": "Tập trung vào đầu, vai, lưng.\nKhi chỉ muốn thư giãn phần thân trên."}, "Eye Relaxation Therapy": {"ko": "눈 주변 혈자리를 눌러 피로를 풀어 줘요.\n화면을 오래 보거나 잠을 설쳤을 때 좋아요.", "en": "Acupressure around the eyes to ease fatigue.\nGood after long screen time or a bad night's sleep.", "vi": "Ấn huyệt vùng mắt giúp giảm mỏi.\nHợp khi nhìn màn hình lâu hoặc ngủ không ngon."}, "Hair & Scalp Care": {"ko": "두피와 머리카락을 깨끗이 씻고 영양을 채워 줘요.\n더위에 땀을 많이 흘린 날 개운하게 마무리하기 좋아요.", "en": "Cleanses and nourishes the scalp and hair.\nA fresh finish on a hot, sweaty day.", "vi": "Làm sạch và nuôi dưỡng tóc, da đầu.\nKết thúc sảng khoái sau một ngày nóng."}, "Natural Skin Care": {"ko": "자연에 가까운 재료로 순하게 하는 기본 얼굴 관리예요.\n피부가 예민해도 부담 없이 받기 좋아요.", "en": "A gentle basic facial with natural ingredients.\nEasy on sensitive skin.", "vi": "Chăm sóc da cơ bản, nhẹ nhàng với nguyên liệu thiên nhiên.\nPhù hợp cả da nhạy cảm."}, "Fresh Oxygen Facial": {"ko": "산소로 피부 속까지 깨끗하게 해 주는 얼굴 관리예요.\n트러블이 걱정되거나 피부가 답답할 때 좋아요.", "en": "An oxygen facial for deep cleansing.\nGood when your skin feels congested or breakout-prone.", "vi": "Liệu pháp oxy làm sạch sâu.\nHợp khi da bí, dễ nổi mụn."}, "Natural Seaweed Brightening": {"ko": "해조 성분으로 피부를 다시 채우고 톤을 밝혀 주는 관리예요.\n피부를 부드럽고 환하게 하고 싶을 때 좋아요.", "en": "Seaweed-based care to renew skin and brighten tone.\nFor softer, brighter-looking skin.", "vi": "Chăm sóc bằng tảo giúp tái tạo và làm sáng da.\nCho làn da mềm mịn, tươi sáng."}, "Intensive Linseed Moisturizing": {"ko": "오메가3가 풍부한 아마씨 성분으로 수분과 영양을 채워 줘요.\n햇볕과 에어컨에 건조해진 피부에 좋아요.", "en": "Linseed, rich in omega-3, for deep moisture and nourishment.\nGood for skin dried out by sun and air-conditioning.", "vi": "Hạt lanh giàu omega-3 cấp ẩm và dưỡng chất.\nHợp với da khô do nắng và máy lạnh."}, "Lingzhi Rejuvenation": {"ko": "영지 성분으로 잔주름과 탄력을 챙기는 관리예요.\n피부에 생기가 없을 때 좋아요.", "en": "Lingzhi mushroom care for fine lines and firmness.\nGood when your skin looks tired.", "vi": "Linh chi giúp cải thiện nếp nhăn, độ săn chắc.\nHợp khi da thiếu sức sống."}, "Collagen & 24K Gold Facial": {"ko": "콜라겐과 24K 금 성분을 쓰는 응오의 가장 고급 얼굴 관리예요.\n탄력과 피부결을 함께 챙기고 싶을 때 좋아요.", "en": "Ngõ's premium facial with collagen and 24K gold.\nFor firmness and smoother texture.", "vi": "Liệu pháp cao cấp với Collagen và vàng 24K.\nCho độ săn chắc và làn da mịn hơn."}, "Body Cleansing Scrub": {"ko": "쌀겨 · 미네랄 소금 · 과일산으로 전신 각질을 벗겨 줘요.\n마사지 전에 받으면 오일이 더 잘 스며들어요.", "en": "Full-body scrub with rice bran, mineral salt and fruit acids.\nHave it before a massage so the oil absorbs better.", "vi": "Tẩy tế bào chết toàn thân với cám gạo, muối khoáng, acid trái cây.\nLàm trước khi massage để dầu thấm tốt hơn."}, "Body Nourishing Wrap": {"ko": "천연 재료를 전신에 바르고 감싸서 영양을 깊이 채워 줘요.\n스크럽과 같이 받으면 피부가 한층 매끈해져요.", "en": "A full-body wrap with natural ingredients for deep nourishment.\nPair it with a scrub for extra-smooth skin.", "vi": "Ủ dưỡng toàn thân với nguyên liệu thiên nhiên.\nKết hợp tẩy tế bào chết để da mịn hơn."}, "Red Dao Herbal Bath": {"ko": "다오족 전통 약초 잎을 우린 물에 몸을 담가요.\n몸이 따뜻해지고 개운해져서, 특히 여성분들이 많이 찾아요.", "en": "Soak in water infused with traditional Red Dao herbal leaves.\nWarming and refreshing — especially popular with women.", "vi": "Ngâm bồn lá Dao đỏ truyền thống.\nLàm ấm và sảng khoái — đặc biệt tốt cho phụ nữ."}}$j$::jsonb as d)
update public.shops s
   set data = jsonb_set(s.data, '{menu}', (
         select jsonb_agg(case when t.d ? (m->'name'->>'en') then m || jsonb_build_object('more', t.d->(m->'name'->>'en')) else m end order by o)
           from jsonb_array_elements(s.data->'menu') with ordinality x(m, o), t))
 where s.id = 'ngo-massage-spa' and jsonb_typeof(s.data->'menu') = 'array';

-- swan-spa · 10종
with t as (select $j${"Signature Basic": {"ko": "스완의 대표 코스예요.\n머리 마사지로 시작해서 아로마 · 핫스톤 전신 마사지, 목 · 어깨 케어까지 한 번에 받아요.\n처음 와서 뭘 받을지 모르겠다면 이걸로 고르면 돼요.", "en": "Swan's signature course.\nStarts with a head massage, then aroma & hot-stone body massage and neck & shoulder care.\nNot sure what to pick? Start here.", "vi": "Liệu trình đặc trưng của Swan.\nMassage đầu, sau đó massage toàn thân với tinh dầu & đá nóng, chăm sóc cổ vai.\nChưa biết chọn gì thì chọn gói này."}, "Signature Basic + Shampoo": {"ko": "시그니처 기본 코스에 샴푸 · 헤어 케어를 더했어요.\n공항 가기 전이나 체크아웃 뒤 머리까지 개운하게 정리하고 싶을 때 좋아요.", "en": "The signature course plus shampoo and hair care.\nGreat before your flight or after check-out.", "vi": "Liệu trình đặc trưng kèm gội đầu & chăm sóc tóc.\nHợp trước giờ bay hoặc sau khi trả phòng."}, "Aroma Body Massage": {"ko": "머리 마사지 뒤에 아로마 오일과 핫스톤으로 전신을 풀어 주고, 목 · 어깨를 마무리해요.\n따뜻하고 부드러운 마사지를 원할 때 좋아요.", "en": "Head massage, then aroma oil and hot stones all over, finishing with neck & shoulders.\nFor a warm, soft massage.", "vi": "Massage đầu, sau đó toàn thân với tinh dầu & đá nóng, kết thúc ở cổ vai.\nCho một buổi massage ấm áp, nhẹ nhàng."}, "Foot Massage": {"ko": "발 각질 정리와 발 마사지에 머리 마사지까지 포함돼 있어요.\n많이 걸은 날, 짧게 받고 다시 다니기 좋아요.", "en": "Foot scrub and foot massage, with a head massage included.\nGreat for a quick reset after lots of walking.", "vi": "Tẩy da chết chân, massage chân, kèm massage đầu.\nThư giãn nhanh sau khi đi bộ nhiều."}, "Four Hands Massage": {"ko": "관리사 두 명이 동시에 마사지해요.\n짧은 시간에 몸 전체가 한꺼번에 풀려서 특별한 경험을 원할 때 좋아요.\n커플이라면 VIP 커플룸(추가 요금)도 물어봐 드려요.", "en": "Two therapists work on you at the same time.\nYour whole body relaxes at once — a special treat.\nFor couples, we can ask about the VIP couple room (extra charge).", "vi": "Hai kỹ thuật viên massage cùng lúc.\nToàn thân được thư giãn cùng lúc — một trải nghiệm đặc biệt.\nCặp đôi có thể hỏi phòng VIP (phụ thu)."}, "Kids Massage": {"ko": "아이를 위한 순한 마사지예요.\n부모님이 마사지 받는 동안 아이도 같이 쉬어 갈 수 있어요.", "en": "A gentle massage for kids.\nThe little ones can relax too while parents get their treatment.", "vi": "Massage nhẹ nhàng cho bé.\nBé cũng được thư giãn khi bố mẹ massage."}, "Hair Wash & Hair Care": {"ko": "샴푸와 헤어 케어예요.\n단독으로 받을 수 있는지는 예약할 때 확인해 드려요.", "en": "Shampoo and hair care.\nWe'll check whether it can be booked on its own.", "vi": "Gội đầu & chăm sóc tóc.\nChúng tôi sẽ xác nhận có đặt riêng được không."}, "Facial Care": {"ko": "30분 얼굴 관리예요. 다른 코스에 더해서 받는 추가 메뉴예요.\n단독으로 받을 수 있는지는 예약할 때 확인해 드려요.", "en": "A 30-minute facial, added to another course.\nWe'll check whether it can be booked on its own.", "vi": "Chăm sóc da mặt 30 phút, thêm vào liệu trình khác.\nChúng tôi sẽ xác nhận có đặt riêng được không."}, "Body Massage": {"ko": "30분 바디 마사지예요. 다른 코스에 더해서 시간을 늘리는 추가 메뉴예요.\n단독으로 받을 수 있는지는 예약할 때 확인해 드려요.", "en": "A 30-minute body massage to extend another course.\nWe'll check whether it can be booked on its own.", "vi": "Massage toàn thân 30 phút để kéo dài liệu trình khác.\nChúng tôi sẽ xác nhận có đặt riêng được không."}, "Foot Massage (short)": {"ko": "30분 발 마사지예요. 다른 코스에 더해서 받는 추가 메뉴예요.\n단독으로 받을 수 있는지는 예약할 때 확인해 드려요.", "en": "A 30-minute foot massage, added to another course.\nWe'll check whether it can be booked on its own.", "vi": "Massage chân 30 phút, thêm vào liệu trình khác.\nChúng tôi sẽ xác nhận có đặt riêng được không."}}$j$::jsonb as d)
update public.shops s
   set data = jsonb_set(s.data, '{menu}', (
         select jsonb_agg(case when t.d ? (m->'name'->>'en') then m || jsonb_build_object('more', t.d->(m->'name'->>'en')) else m end order by o)
           from jsonb_array_elements(s.data->'menu') with ordinality x(m, o), t))
 where s.id = 'swan-spa' and jsonb_typeof(s.data->'menu') = 'array';

-- golden-lotus-spa · 5종
with t as (select $j${"VIP Golden Lotus": {"ko": "골든 로터스의 가장 좋은 코스예요.\nVIP 개인실에서 프랑스 아로마 오일 마사지를 받고, 발 소금 스크럽 · 얼굴 팩까지 해 줘요.\n샤워 · 열대 과일 · 음료가 포함돼 있어요.", "en": "Golden Lotus's top course.\nFrench aroma oil massage in a VIP private room, with a foot salt scrub and face mask.\nShower, tropical fruit and drinks included.", "vi": "Gói cao cấp nhất của Golden Lotus.\nMassage tinh dầu Pháp trong phòng VIP riêng, kèm tẩy da chết chân bằng muối và đắp mặt nạ.\nBao gồm tắm, trái cây nhiệt đới và đồ uống."}, "Sauna + foot massage": {"ko": "사우나로 몸을 데운 뒤 편한 의자에서 발 마사지를 받아요.\n건식 사우나 · 스팀 · 냉온 자쿠지 같은 시설은 이용 범위를 예약할 때 확인해 드려요.", "en": "Warm up in the sauna, then a foot massage in a comfy armchair.\nWe'll confirm which facilities (dry sauna, steam, hot & cold jacuzzi) are included when you book.", "vi": "Xông hơi làm ấm cơ thể, sau đó massage chân trên ghế bành.\nCác tiện ích (xông khô, xông ướt, bể sục nóng lạnh) sẽ được xác nhận khi đặt lịch."}, "Full-body massage": {"ko": "머리부터 발끝까지 전신을 풀어 주는 기본 마사지예요.\n23년째 운영해 온 곳이에요.", "en": "A head-to-toe full-body massage.\nA spa that has been running for 23 years.", "vi": "Massage toàn thân từ đầu đến chân.\nSpa đã hoạt động 23 năm."}, "Oil massage": {"ko": "오일을 바르고 부드럽게 쓸어 주는 전신 마사지예요.\n세게 누르는 것보다 편하게 쉬고 싶을 때 좋아요.", "en": "A smooth full-body oil massage.\nFor relaxing rather than strong pressure.", "vi": "Massage toàn thân với dầu, nhẹ nhàng.\nDành cho người muốn thư giãn hơn là lực mạnh."}, "Facial massage": {"ko": "클렌징 · 스팀 · 마사지로 짧게 받는 얼굴 관리예요.\n햇볕에 지친 얼굴을 개운하게 정리해 줘요.", "en": "A quick facial with cleansing, steam and massage.\nFreshens up sun-tired skin.", "vi": "Chăm sóc da mặt nhanh: làm sạch, xông hơi, massage.\nGiúp da mặt tươi tỉnh sau nắng."}}$j$::jsonb as d)
update public.shops s
   set data = jsonb_set(s.data, '{menu}', (
         select jsonb_agg(case when t.d ? (m->'name'->>'en') then m || jsonb_build_object('more', t.d->(m->'name'->>'en')) else m end order by o)
           from jsonb_array_elements(s.data->'menu') with ordinality x(m, o), t))
 where s.id = 'golden-lotus-spa' and jsonb_typeof(s.data->'menu') = 'array';

-- la-belle-spa · 37종
with t as (select $j${"La Belle Vie Unique Treatment": {"ko": "데운 돌과 대나무를 함께 쓰는 라벨비 대표 코스예요.\n90분이면 생과일주스와 허브 스팀, 120분이면 식사까지 무료로 줘요.", "en": "La Belle Vie's signature course with warm stones and bamboo.\n90': fresh juice and herbal steam included; 120': a free meal too.", "vi": "Liệu trình đặc trưng với đá nóng và ống tre.\n90 phút: tặng nước ép và xông hơi thảo dược; 120 phút: tặng thêm bữa ăn."}, "La Belle Vie Gorgeous Treatment": {"ko": "돌 · 대나무 · 허브를 모두 쓰는 한 단계 위 코스예요.\n90분이면 주스와 스팀, 120분이면 식사와 20분 얼굴 관리까지 무료예요.", "en": "A step up — stones, bamboo and herbs together.\n90': juice and steam; 120': a meal plus a 20-minute facial, free.", "vi": "Cao cấp hơn — đá, ống tre và thảo dược.\n90 phút: nước ép và xông hơi; 120 phút: thêm bữa ăn và 20 phút chăm sóc da mặt."}, "Judo Bamboo & Hot Stone Therapy": {"ko": "오일 없이 하는 유도식 테라피에 대나무 · 핫스톤을 더했어요.\n오일이 싫거나 옷을 입고 받고 싶은 분께 맞아요.", "en": "Oil-free judo-style therapy with bamboo and hot stones.\nGood if you'd rather skip oil.", "vi": "Trị liệu kiểu judo không dầu, kết hợp ống tre và đá nóng.\nHợp với người không thích dầu."}, "Luxury Vietnamese Traditional massage": {"ko": "베트남 전통 마사지에 딥티슈와 스트레칭을 더한 코스예요.\n뭉친 곳을 확실히 풀고 싶을 때 좋아요.", "en": "Vietnamese traditional massage plus deep tissue and stretching.\nFor really working out knots.", "vi": "Massage truyền thống Việt Nam kết hợp deep tissue và kéo giãn.\nGiải tỏa các điểm căng cứng."}, "Luxury Four Hands massage": {"ko": "관리사 두 명이 동시에 마사지해요.\n짧은 시간에 몸 전체가 한꺼번에 풀려요.", "en": "Two therapists at the same time.\nYour whole body relaxes at once.", "vi": "Hai kỹ thuật viên cùng lúc.\nToàn thân được thư giãn cùng lúc."}, "Gorgeous Four Hands Massage": {"ko": "관리사 두 명이 대나무 · 핫스톤으로 동시에 풀어 줘요.\n포핸즈에 도구까지 더해 더 시원해요.", "en": "Two therapists working with bamboo and hot stones.\nFour hands plus tools for a deeper release.", "vi": "Hai kỹ thuật viên với ống tre và đá nóng.\nBốn tay cộng dụng cụ để thư giãn sâu hơn."}, "La Belle Vie Four Hands Massage": {"ko": "관리사 두 명이 대나무 · 핫스톤 · 허브를 모두 써요.\n120분이면 공항 편도 이동이 무료예요.", "en": "Two therapists with bamboo, hot stones and herbs.\n120': free one-way airport transfer.", "vi": "Hai kỹ thuật viên với ống tre, đá nóng và thảo dược.\n120 phút: miễn phí đưa đón sân bay một chiều."}, "Imperial Balance Therapy": {"ko": "유도식 테라피에 타이 스트레칭을 섞었어요.\n몸이 뻣뻣하고 자세가 무너진 느낌일 때 좋아요.", "en": "Judo-style therapy blended with Thai stretching.\nGood when you feel stiff and out of alignment.", "vi": "Trị liệu kiểu judo kết hợp kéo giãn Thái.\nHợp khi cơ thể cứng, mất cân bằng."}, "Elite Recovery Therapy": {"ko": "유도식 테라피에 따뜻한 허브 밤을 더한 회복 코스예요.\n120분이면 공항 편도 이동이 무료예요.", "en": "A recovery course: judo-style therapy with warm herbal balm.\n120': free one-way airport transfer.", "vi": "Liệu trình phục hồi: trị liệu kiểu judo với cao thảo dược ấm.\n120 phút: miễn phí đưa đón sân bay một chiều."}, "Judo Hattori Takuma Therapy": {"ko": "엉덩이 · 척추 · 날개뼈 · 사타구니 쪽을 집중해서 풀어 줘요.\n오래 앉아 있거나 많이 걸어서 골반 주변이 뻐근할 때 좋아요.", "en": "Focuses on the glutes, spine, shoulder blades and groin.\nGood for a tight hip area after long sitting or walking.", "vi": "Tập trung vào mông, cột sống, xương bả vai và háng.\nHợp khi vùng hông căng cứng do ngồi hoặc đi lâu."}, "Bioelectric Massage": {"ko": "생체 전기 방식과 동양 의학 기법을 섞은 마사지예요.\n다른 곳에서 받기 어려운 색다른 마사지를 원할 때 좋아요.", "en": "Bioelectric method blended with oriental medicine techniques.\nFor something you won't find everywhere.", "vi": "Phương pháp điện sinh học kết hợp kỹ thuật đông y.\nMột trải nghiệm khác biệt."}, "La Belle Vie Signature Bamboo massage": {"ko": "따뜻하게 데운 대나무로 깊게 풀어 주는 라벨비 시그니처예요.\n손보다 넓고 고르게 눌러 줘서 시원해요.", "en": "La Belle Vie's signature — warm bamboo with deep tissue.\nWide, even pressure that feels great.", "vi": "Đặc trưng của La Belle Vie — ống tre ấm kết hợp deep tissue.\nLực đều, rộng, rất dễ chịu."}, "Signature massage": {"ko": "진행 순서\n① 허브 족욕\n② 오일 마사지\n③ 타이 허브볼 찜질\n④ 베트남 헤드 마사지\n\n여러 가지를 조금씩 다 받아 보고 싶을 때 좋아요.", "en": "How it goes\n① Herbal foot ritual\n② Oil massage\n③ Thai herbal compress\n④ Vietnamese head massage\n\nA little of everything.", "vi": "Quy trình\n① Ngâm chân thảo dược\n② Massage dầu\n③ Chườm bóng thảo dược Thái\n④ Massage đầu kiểu Việt\n\nMỗi thứ một chút."}, "Royal Matrix Massage": {"ko": "관리사 네 명이 함께 하는 라벨비의 가장 특별한 코스예요.\n허브 찜질 · 대나무 · 핫스톤을 쓰고 식사도 포함돼요.\n90분이면 공항 편도 이동이 무료예요.", "en": "La Belle Vie's most special course — four therapists at once.\nHerbal compress, bamboo and hot stones, with a meal included.\n90': free one-way airport transfer.", "vi": "Liệu trình đặc biệt nhất — bốn kỹ thuật viên cùng lúc.\nChườm thảo dược, ống tre, đá nóng, kèm bữa ăn.\n90 phút: miễn phí đưa đón sân bay một chiều."}, "Hot Stone Therapy": {"ko": "데운 돌로 근육을 깊게 풀어 주는 마사지예요.\n90분이면 스무디, 120분이면 식사가 무료예요.", "en": "Heated stones to release deep muscles.\n90': free smoothie; 120': free meal.", "vi": "Đá nóng giúp thư giãn sâu cơ bắp.\n90 phút: tặng sinh tố; 120 phút: tặng bữa ăn."}, "Asian Blend massage": {"ko": "타이 · 베트남 · 시아추(일본식 지압)를 섞은 마사지예요.\n엄지 · 팔꿈치로 누르고 스트레칭을 해 줘서 세게 받고 싶은 분께 맞아요.", "en": "A blend of Thai, Vietnamese and shiatsu.\nThumbs, elbows and stretches — for those who like it firm.", "vi": "Kết hợp massage Thái, Việt và shiatsu.\nDùng ngón cái, khuỷu tay và kéo giãn — hợp với người thích lực mạnh."}, "Traditional Vietnamese massage": {"ko": "베트남 전통 지압에 아로마 오일을 더한 마사지예요.\n베트남에 왔으니 한 번은 받아 볼 만해요.", "en": "Vietnamese pressure-point massage with aroma oil.\nWorth trying once while you're in Vietnam.", "vi": "Massage bấm huyệt truyền thống Việt Nam với tinh dầu."}, "Traditional Thai massage": {"ko": "오일 없이 지압과 스트레칭으로 풀어 주는 타이 마사지예요.\n몸이 뻣뻣할 때 좋아요.", "en": "Oil-free Thai massage with pressure and stretching.\nGreat when you feel stiff.", "vi": "Massage Thái không dầu, bấm huyệt và kéo giãn.\nHợp khi cơ thể cứng mỏi."}, "Aromatherapy": {"ko": "4가지 블렌딩 오일 중 하나를 골라서 받아요.\n압은 약하게~중간이라 편하게 쉬고 싶을 때 좋아요.", "en": "Choose one of four blended oils.\nLight to medium pressure — for pure relaxation.", "vi": "Chọn một trong bốn loại tinh dầu pha.\nLực nhẹ đến vừa — để thư giãn."}, "The charm of pregnant Treatment": {"ko": "임신 중인 분을 위한 마사지예요. 천연 오일과 따뜻한 돌을 써요.\n임신 주수는 예약할 때 알려 주세요.", "en": "A prenatal massage with natural oils and warm stones.\nPlease tell us how many weeks along you are when booking.", "vi": "Massage cho mẹ bầu với dầu thiên nhiên và đá ấm.\nVui lòng cho biết tuần thai khi đặt lịch."}, "Children Care Therapy": {"ko": "아이를 위한 허브 오일 마사지예요.\n부모님이 받는 동안 아이도 같이 쉬어 갈 수 있어요.", "en": "A herbal-oil massage for children.\nKids can relax too while parents get their treatment.", "vi": "Massage tinh dầu thảo dược cho bé.\nBé cũng được thư giãn khi bố mẹ massage."}, "Back - Shoulder - Head Therapy": {"ko": "타이 · 딥티슈 기법으로 등 · 어깨 · 목을 집중해서 풀어 줘요.\n상체만 시원하게 받고 싶을 때 좋아요.", "en": "Thai and deep-tissue work on the back, shoulders and neck.\nWhen you want just the upper body done.", "vi": "Kỹ thuật Thái và deep tissue cho lưng, vai, cổ.\nKhi chỉ muốn thư giãn phần thân trên."}, "Stones Back massage": {"ko": "데운 돌로 등을 집중해서 풀어 줘요.\n짧은 시간에 등을 따뜻하게 풀고 싶을 때 좋아요.", "en": "Heated stones focused on the back.\nA quick, warm back release.", "vi": "Đá nóng tập trung vào lưng.\nThư giãn lưng nhanh và ấm."}, "Bamboo back massage": {"ko": "대나무와 허브볼로 등을 풀고, 베트남 헤드 마사지로 마무리해요.", "en": "Bamboo and herbal compress on the back, finishing with a Vietnamese head massage.", "vi": "Ống tre và bóng thảo dược cho lưng, kết thúc bằng massage đầu kiểu Việt."}, "Lux Unique Back – Shoulder – Head": {"ko": "데운 돌과 대나무로 머리 · 어깨 · 등을 풀어 줘요.\n대표 코스(유니크)의 상체 버전이에요.", "en": "Warm stones and bamboo on the head, shoulders and back.\nThe upper-body version of the Unique course.", "vi": "Đá ấm và ống tre cho đầu, vai, lưng.\nPhiên bản phần thân trên của Unique."}, "Gorgeous Treatment Back – Shoulder – Head": {"ko": "돌 · 대나무 · 허브로 머리 · 어깨 · 등을 풀어 줘요.\n고저스 코스의 상체 버전이에요.", "en": "Stones, bamboo and herbs on the head, shoulders and back.\nThe upper-body version of the Gorgeous course.", "vi": "Đá, ống tre và thảo dược cho đầu, vai, lưng.\nPhiên bản phần thân trên của Gorgeous."}, "Bioelectric Back Treatment": {"ko": "생체 전기 방식으로 등을 관리해요.\n등이 자주 뭉치는 분께 색다른 선택이에요.", "en": "Bioelectric care for the back.\nA different option if your back tightens up often.", "vi": "Chăm sóc lưng bằng phương pháp điện sinh học.\nLựa chọn khác biệt cho người hay mỏi lưng."}, "Bioelectric Herbal Back massage": {"ko": "생체 전기 방식에 허브볼 찜질을 더하고, 베트남 헤드 마사지로 마무리해요.", "en": "Bioelectric back care with herbal compress, finishing with a Vietnamese head massage.", "vi": "Điện sinh học kết hợp chườm thảo dược cho lưng, kết thúc bằng massage đầu."}, "Vietnamese Head massage": {"ko": "베트남식으로 머리를 눌러 주고 풀어 주는 마사지예요.\n두통이 있거나 머리가 무거울 때 좋아요.", "en": "A Vietnamese-style head massage.\nGood when your head feels heavy.", "vi": "Massage đầu kiểu Việt Nam.\nHợp khi đầu nặng, căng thẳng."}, "Herbal Steam": {"ko": "허브를 넣은 스팀 사우나예요.\n마사지 전에 하면 몸이 미리 풀려서 더 좋아요.", "en": "An herbal steam sauna.\nBest before a massage to warm up.", "vi": "Xông hơi thảo dược.\nTốt nhất trước khi massage."}, "Foot Reflexology": {"ko": "발바닥 반사구를 눌러 주는 발 마사지예요.\n많이 걸은 날 붓기를 풀기 좋아요.", "en": "Pressure-point foot reflexology.\nGreat for tired, swollen feet.", "vi": "Bấm huyệt phản xạ bàn chân.\nHợp với chân mỏi, sưng."}, "Luxury Foot massage": {"ko": "데운 돌과 대나무를 쓰고 발 반사 마사지까지 해 줘요.\n일반 발 마사지보다 한 단계 더 시원해요.", "en": "Warm stones and bamboo plus reflexology.\nA step up from a regular foot massage.", "vi": "Đá ấm, ống tre kèm bấm huyệt chân.\nCao cấp hơn massage chân thông thường."}, "Bioelectric Foot massage": {"ko": "생체 전기 방식과 대나무에 발 반사 마사지를 더했어요.", "en": "Bioelectric method and bamboo with foot reflexology.", "vi": "Điện sinh học, ống tre kèm bấm huyệt chân."}, "Oat Milk Moisturizing Body Scrub": {"ko": "꿀 · 허브 · 쌀우유로 각질을 정리하고 촉촉하게 채워 줘요.\n건조한 피부에 좋아요.", "en": "Honey, herbs and rice milk to exfoliate and moisturize.\nGood for dry skin.", "vi": "Mật ong, thảo dược và sữa gạo tẩy tế bào chết và dưỡng ẩm.\nHợp với da khô."}, "Green Tea Scrub": {"ko": "녹차로 각질을 정리해서 칙칙한 피부 톤을 밝혀 줘요.", "en": "A green tea scrub to brighten dull skin.", "vi": "Tẩy tế bào chết bằng trà xanh, giúp da sáng hơn."}, "Dead sea - Salt Scrub": {"ko": "사해 소금으로 깊이 각질을 벗기고 미네랄을 채워 줘요.\n피부결을 매끈하게 하고 싶을 때 좋아요.", "en": "Dead Sea salt for deep exfoliation and minerals.\nFor smoother skin texture.", "vi": "Muối Biển Chết tẩy tế bào chết sâu, bổ sung khoáng chất.\nCho làn da mịn màng."}, "Vietnamese Coconut Scrub": {"ko": "코코넛으로 순하게 각질을 정리해요.\n피부가 예민해도 부담 없어요.", "en": "A gentle coconut scrub.\nEasy on sensitive skin.", "vi": "Tẩy tế bào chết nhẹ nhàng bằng dừa.\nPhù hợp cả da nhạy cảm."}}$j$::jsonb as d)
update public.shops s
   set data = jsonb_set(s.data, '{menu}', (
         select jsonb_agg(case when t.d ? (m->'name'->>'en') then m || jsonb_build_object('more', t.d->(m->'name'->>'en')) else m end order by o)
           from jsonb_array_elements(s.data->'menu') with ordinality x(m, o), t))
 where s.id = 'la-belle-spa' and jsonb_typeof(s.data->'menu') = 'array';

-- 확인: 업체별 자세히 보기가 붙은 메뉴 수
select id, jsonb_array_length(data->'menu') as menus,
       (select count(*) from jsonb_array_elements(data->'menu') m where m ? 'more') as with_more
  from public.shops where id in ('ngo-massage-spa', 'swan-spa', 'golden-lotus-spa', 'la-belle-spa') order by id;
